        activeVehicleKey = originalKey
        audioEngine.setCharacter(originalCharacter)
        previewVehicleKey = null
        toast("试听会话准备失败，请停止当前播放后重试")
        return
    }
    if (!audioEngine.start()) {
        audioEngine.setVehicle(originalKey)
        activeVehicleKey = originalKey
        audioEngine.setCharacter(originalCharacter)
        previewVehicleKey = null
        toast("试听启动失败，请检查音频输出设备")
